    'cloud_domain_change' => 'Tin tốt! Miền đám mây của bạn đã được thay đổi thành công. Lưu ý rằng sẽ có một thời gian gián đoạn ngắn khoảng 5 phút để áp dụng các thay đổi này. Cảm ơn bạn đã kiên nhẫn!',
    'limit_is_up' => 'Chúng tôi nhận thấy bạn đã vượt quá giới hạn dùng thử miễn phí, vui lòng xóa các phiên bản hiện tại của bạn để tiếp tục.',
