    'cloud_domain_empty' => 'Ôi không! Bạn không thể tạo hóa đơn cho kế hoạch này mà không cung cấp miền.',
    'domain_taken' => 'Ôi không! Có vẻ như miền này đã được sử dụng bởi người dùng khác. Vui lòng thử với một miền khác.',
    'without_installation_found' => 'Ôi không! Có vẻ như bạn không thể thay đổi các đại lý nếu chúng tôi không thể tìm thấy miền đám mây của bạn. Vui lòng gia hạn đăng ký trước, và thực hiện các thay đổi cần thiết cho đại lý sau. Bạn có thể điều chỉnh số đại lý trong cài đặt đám mây của bạn dưới đơn hàng của bạn. Cảm ơn bạn!',
    'nothing_changed' => 'Đừng lo lắng! Có vẻ như không có thay đổi nào – miền hiện tại và miền mới của bạn dường như giống nhau. Nếu bạn có bất kỳ câu hỏi nào hoặc cần thêm sự trợ giúp, đừng ngần ngại liên hệ!',
    'cloud_not_allowed' => 'Chỉ muốn thông báo! Bạn không được phép cập nhật tên miền phụ liên kết với faveocloud.com. Nếu bạn muốn thay đổi miền của mình, vui lòng sử dụng tên miền tùy chỉnh của riêng bạn. Nếu bạn cần sự giúp đỡ hoặc có câu hỏi, đừng ngần ngại yêu cầu!',
    'installation_path_not_found' => 'Có vẻ như bạn không thể thay đổi đơn hàng này nếu chúng tôi không thể tìm thấy miền đám mây của bạn. Cảm ơn bạn!',
    'wrong_agents' => 'Ôi không, có vẻ như đã xảy ra một sự cố nhỏ! Đội ngũ của chúng tôi đang xử lý và sẽ khắc phục sớm. Khi vấn đề được giải quyết, bạn sẽ có thể thay đổi đại lý của mình. Cảm ơn bạn đã kiên nhẫn!',
    'wrong_upgrade' => 'Ôi không, có vẻ như đã xảy ra một sự cố nhỏ! Đội ngũ của chúng tôi đang xử lý và sẽ khắc phục sớm. Khi vấn đề được giải quyết, bạn sẽ có thể nâng cấp hoặc hạ cấp kế hoạch hiện tại của mình. Cảm ơn bạn đã kiên nhẫn!',
    'wrong_domain' => 'Ôi không, có vẻ như đã xảy ra một sự cố nhỏ! Đội ngũ của chúng tôi đang xử lý và sẽ khắc phục sớm. Khi vấn đề được giải quyết, bạn sẽ có thể tùy chỉnh tên miền của mình. Cảm ơn bạn đã kiên nhẫn!',
    'agent_updated' => 'Woohoo! Chúng tôi đã cập nhật thành công số đại lý trong kế hoạch hiện tại của bạn. Tất cả đã sẵn sàng!',
    'change_agents_failed' => 'Ôi không! Trong khi bạn đang chỉnh sửa đại lý, có vẻ như có một sự cố nhỏ xảy ra trên máy chủ đám mây. Đừng lo – đội ngũ của chúng tôi đang xử lý và sẽ khắc phục sự cố!',
    'agent_reduce' => 'Ôi không! Bạn không thể giảm số lượng đại lý trong kế hoạch này ngay bây giờ. Có vẻ như bạn có một số đại lý đang hoạt động trong tài khoản. Chúng tôi khuyên bạn tắt bất kỳ đại lý thừa nào trước khi thử điều chỉnh số lượng đại lý trong kế hoạch.',
    'not_allowed_domain' => 'Ôi không! Có vẻ như bạn đã nhập một định dạng tên miền không hợp lệ, không được phép trên internet. Vui lòng nhập một tên miền hợp lệ để tiếp tục.',
    'agent_zero' => 'Có vẻ như bạn đã chọn số đại lý bằng không. Vui lòng chọn một số đại lý hợp lệ để tiếp tục.',
