    'no_description_available' => 'Không có mô tả nào.',
    'gateway_desc_paypal' => 'Chấp nhận thanh toán trên toàn thế giới bằng PayPal — một trong những nền tảng thanh toán trực tuyến đáng tin cậy nhất hỗ trợ hơn 200 quốc gia và nhiều loại tiền tệ.',
    'gateway_desc_stripe' => 'Xử lý thẻ, ví và phương thức thanh toán địa phương trên toàn cầu với cơ sở hạ tầng thanh toán mạnh mẽ thân thiện với nhà phát triển của Stripe.',
    'gateway_desc_razorpay' => 'Cổng thanh toán hàng đầu của Ấn Độ hỗ trợ UPI, thẻ, ngân hàng trực tuyến, ví và EMI với trải nghiệm thanh toán liền mạch.',
    'gateway_desc_amazon' => 'Cho phép khách hàng thanh toán bằng thông tin đăng nhập tài khoản Amazon của họ để có trải nghiệm thanh toán nhanh chóng, đáng tin cậy và quen thuộc.',
    'gateway_desc_google' => 'Cho phép thanh toán nhanh chóng và an toàn với Google Pay — hoạt động trên Android, Chrome và web.',
    'gateway_desc_apple' => 'Cho phép người dùng thiết bị Apple thanh toán nhanh chóng và an toàn bằng Face ID, Touch ID hoặc mật mã qua Apple Pay.',
    'gateway_desc_mollie' => 'Cổng thanh toán linh hoạt của Châu Âu cung cấp thẻ, iDEAL, Bancontact, SEPA và nhiều phương thức địa phương khác.',
    'gateway_desc_paytm' => 'Ví kỹ thuật số và cổng thanh toán phổ biến của Ấn Độ hỗ trợ UPI, thẻ, ngân hàng trực tuyến và ví Paytm.',
    'gateway_desc_cashfree' => 'Cổng thanh toán nhanh chóng và đáng tin cậy dành cho các doanh nghiệp Ấn Độ với sự hỗ trợ thanh toán, đăng ký và thanh toán tức thì.',
    'gateway_desc_instamojo' => 'Cổng thanh toán đơn giản dành cho SMB Ấn Độ — chấp nhận thanh toán qua liên kết, UPI, thẻ và ví với phí thiết lập bằng 0.',
    'gateway_desc_flutterwave' => 'Nền tảng thanh toán xuyên châu Phi cho phép các doanh nghiệp chấp nhận và gửi thanh toán trên khắp Châu Phi và hơn thế nữa.',
    'gateway_desc_paystack' => 'Cổng thanh toán hàng đầu Châu Phi hỗ trợ thẻ, chuyển khoản ngân hàng, USSD và tiền di động.',
    'gateway_desc_square' => 'Giải pháp thương mại hợp nhất với thanh toán trực tuyến và trực tiếp, quản lý hàng tồn kho và phân tích kinh doanh.',
    'gateway_desc_braintree' => 'Dịch vụ PayPal cung cấp tích hợp thanh toán linh hoạt với sự hỗ trợ cho thẻ, PayPal, Venmo và các phương thức địa phương.',
    'gateway_desc_authorize' => 'Một trong những cổng thanh toán uy tín nhất ở Hoa Kỳ, cung cấp khả năng xử lý thẻ an toàn và phát hiện gian lận.',
    'gateway_desc_ccavenue' => 'Cổng thanh toán lớn nhất Ấn Độ với hơn 200 tùy chọn thanh toán bao gồm thẻ, ngân hàng trực tuyến, UPI và ví.',
    'gateway_desc_payu' => 'Nền tảng thanh toán toàn cầu có mặt tại hơn 50 thị trường, hỗ trợ các phương thức thanh toán địa phương và quốc tế.',
    'gateway_desc_worldpay' => 'Công ty dẫn đầu toàn cầu về xử lý thanh toán — chấp nhận thẻ và các phương thức thanh toán thay thế trên 146 quốc gia.',
    'gateway_desc_klarna' => 'Cung cấp gói mua ngay trả sau, gói trả góp và các tùy chọn tài chính linh hoạt để tăng cường chuyển đổi khi thanh toán.',
    'gateway_desc_afterpay' => 'Cho khách hàng chia mua hàng thành 4 đợt không lãi suất, tăng giá trị trung bình đơn hàng và chuyển đổi.',
    'webhook_secret' => 'Bí mật webhook',
    'webhook_purpose_subscription_charged' => 'Cần thiết để tính năng tự động gia hạn thực sự hoạt động — nếu không có tính năng này, các đăng ký được gia hạn sẽ không được gia hạn ngay cả sau khi Razorpay tính phí cho khách hàng.',
    'webhook_purpose_subscription_pending' => 'Bắt buộc phải ghi lại khoản phí gia hạn không thành công trong lần thử đầu tiên — nếu không có nó, việc tự động gia hạn đang gặp khó khăn sẽ không thể nhìn thấy được cho đến khi Razorpay dùng hết tất cả các lần thử lại.',
    'webhook_purpose_subscription_halted' => 'Cần thiết để phát hiện các lần gia hạn không thành công - nếu không có nó, ứng dụng sẽ không biết khoản phí định kỳ đã ngừng hoạt động và tính năng tự động gia hạn vẫn bị hỏng một cách âm thầm.',
    'webhook_purpose_payment_captured' => 'Bắt buộc phải xác nhận thanh toán hóa đơn/đơn hàng — nếu không có xác nhận này, khách hàng có thể thanh toán thành công và hóa đơn vẫn không được đánh dấu là đã thanh toán.',
    'webhook_purpose_payment_failed' => 'Cần thiết để phát hiện các khoản thanh toán không thành công - nếu không có nó, nỗ lực thanh toán không thành công sẽ không được chú ý và khách hàng sẽ không bao giờ được yêu cầu thử lại.',
    'webhook_purpose_invoice_payment_succeeded' => 'Cần thiết để tính năng tự động gia hạn thực sự hoạt động — nếu không có tính năng này, các đăng ký được gia hạn sẽ không được gia hạn ngay cả sau khi Stripe tính phí cho khách hàng.',
    'webhook_purpose_invoice_payment_failed' => 'Cần thiết để phát hiện các lần gia hạn không thành công — nếu không có nó, ứng dụng sẽ không biết khoản phí định kỳ đã ngừng hoạt động và tính năng tự động gia hạn vẫn bị hỏng một cách âm thầm.',
    'webhook_purpose_customer_subscription_deleted' => 'Cần phải giữ trạng thái tự động gia hạn chính xác — nếu không có nó, đăng ký bị hủy trong Stripe vẫn hiển thị là đang hoạt động ở đây.',
    'webhook_purpose_checkout_session_completed' => 'Bắt buộc phải xác nhận các khoản thanh toán hóa đơn/đơn hàng được thực hiện qua Checkout được nhúng — nếu không có nó, khách hàng có thể thanh toán thành công và hóa đơn vẫn không được đánh dấu là đã thanh toán.',
    'webhook_purpose_payment_intent_succeeded' => 'Bắt buộc phải xác nhận các khoản thanh toán hóa đơn/đơn hàng được thực hiện bằng thẻ — nếu không có thẻ, khách hàng có thể thanh toán thành công và hóa đơn vẫn không được đánh dấu là đã thanh toán.',
    'webhook_purpose_payment_intent_payment_failed' => 'Cần thiết để phát hiện các khoản thanh toán không thành công - nếu không có nó, nỗ lực thanh toán không thành công sẽ không được chú ý và khách hàng sẽ không bao giờ được yêu cầu thử lại.',
